   "example": {
    "title": "Путь одного имени проекта",
    "text": "У проекта уже есть репозиторий и страница в хранилище, а записи в общей базе нет. Онбординг находит существующее по краткому имени и показывает один план с пометками «создать», «переиспользовать», «заблокировано»: локально не хватает только строки в файле маршрутизации, в общей базе создаётся запись проекта с темой, в Yonote — страница внутри карточки темы и доска «КОД · Задачи», видимая участникам. После подтверждения заводится только недостающее, ключ Yonote при этом держит служба, а не компьютер участника. В конце каждая связь перечитывается: то, что не подтвердилось чтением, остаётся названной нехваткой."
   },
